a3=A.ax(0,"L2-23",2,A.a([A.f("The average price weighted by volume within a session","Gi\xe1 trung b\xecnh c\xf3 tr\u1ecdng s\u1ed1 theo kh\u1ed1i l\u01b0\u1ee3ng trong phi\xean","\u67d0\u4ea4\u6613\u65f6\u6bb5\u5185\u6309\u6210\u4ea4\u91cf\u52a0\u6743\u7684\u5e73\u5747\u4ef7\u683c","\u30bb\u30c3\u30b7\u30e7\u30f3\u5185\u3067\u51fa\u6765\u9ad8\u52a0\u91cd\u3057\u305f\u5e73\u5747\u4fa1\u683c","\uc138\uc158 \ub0b4\uc5d0\uc11c \uac70\ub798\ub7c9\uc73c\ub85c \uac00\uc911 \ud3c9\uade0\ud55c \uac00\uaca9"),A.f("The highest closing price of the week","Gi\xe1 \u0111\xf3ng c\u1eeda cao nh\u1ea5t trong tu\u1ea7n","\u672c\u5468\u6700\u9ad8\u6536\u76d8\u4ef7","\u9031\u9593\u6700\u9ad8\u7d42\u5024","\uc8fc\uac04 \ucd5c\uace0 \uc885\uac00"),A.f("A type of Stop order","M\u1ed9t lo\u1ea1i l\u1ec7nh Stop",b6,b7,"\uc190\uc808 \uc8fc\ubb38\uc758 \ud55c \uc885\ub958"),A.f("An indicator measuring sentiment via social media","Ch\u1ec9 b\xe1o \u0111o t\xe2m l\xfd th\u1ecb tr\u01b0\u1eddng qua m\u1ea1ng x\xe3 h\u1ed9i","\u901a\u8fc7\u793e\u4ea4\u5a92\u4f53\u8861\u91cf\u60c5\u7eea\u7684\u6307\u6807","SNS\u3067\u5fc3\u7406\u3092\u6e2c\u308b\u6307\u6a19","\uc18c\uc15c\ubbf8\ub514\uc5b4\ub85c \uc2ec\ub9ac\ub97c \uce21\uc815\ud558\ub294 \uc9c0\ud45c")],f9),a4,a3)
