e5=A.ax(0,"L3-02",3,A.a([A.f("An early signal that the current structure may be reversing","T\xedn hi\u1ec7u s\u1edbm cho th\u1ea5y c\u1ea5u tr\xfac xu h\u01b0\u1edbng hi\u1ec7n t\u1ea1i c\xf3 th\u1ec3 \u0111ang \u0111\u1ea3o chi\u1ec1u","\u5f53\u524d\u7ed3\u6784\u53ef\u80fd\u6b63\u5728\u53cd\u8f6c\u7684\u65e9\u671f\u4fe1\u53f7","\u73fe\u5728\u306e\u69cb\u9020\u304c\u53cd\u8ee2\u3059\u308b\u53ef\u80fd\u6027\u3092\u793a\u3059\u65e9\u671f\u30b7\u30b0\u30ca\u30eb","\ud604\uc7ac \uad6c\uc870\uac00 \ubc18\uc804\ub420 \uc218 \uc788\uc74c\uc744 \uc54c\ub9ac\ub294 \uc870\uae30 \uc2e0\ud638"),A.f("Confirmation that the old trend is continuing even stronger","X\xe1c nh\u1eadn xu h\u01b0\u1edbng c\u0169 ti\u1ebfp di\u1ec5n m\u1ea1nh h\u01a1n","\u65e7\u8d8b\u52bf\u6b63\u5728\u66f4\u5f3a\u52b2\u5ef6\u7eed\u7684\u786e\u8ba4","\u65e2\u5b58\u306e\u30c8\u30ec\u30f3\u30c9\u304c\u3088\u308a\u5f37\u304f\u7d9a\u304f\u3053\u3068\u3092\u78ba\u8a8d\u3059\u308b\u3082\u306e","\uae30\uc874 \ucd94\uc138\uac00 \ub354 \uac15\ud558\uac8c \uc774\uc5b4\uc9c0\ub294 \uac83\uc744 \ud655\uc778\ud568"),A.f("A volume indicator","M\u1ed9t ch\u1ec9 b\xe1o \u0111o kh\u1ed1i l\u01b0\u1ee3ng","\u4e00\u79cd\u6210\u4ea4\u91cf\u6307\u6807","\u51fa\u6765\u9ad8\u6307\u6a19","\uac70\ub798\ub7c9 \uc9c0\ud45c"),A.f("Exactly the same thing as BOS","\u0110\u1ed3ng ngh\u0129a ho\xe0n to\xe0n v\u1edbi BOS","\u4e0eBOS\u5b8c\u5168\u76f8\u540c","BOS\u3068\u5168\u304f\u540c\u3058\u3082\u306e","BOS\uc640 \uc644\uc804\ud788 \ub3d9\uc77c\ud568")],e6),q,e5)
